{
  "recommendation": {
    "best_choice": "B then C (with optional A first)",
    "summary": "If you suspect secrets were changed or compromised, the safest path is to verify and rotate affected secrets first (B) and then resend pending webhooks (C). If you want immediate visibility before authorizing rotations, request the redacted error summary (A) and then proceed with B→C."
  },
  "recommended_sequence": [
    "Optional: Deliver a redacted error summary (A) so you can confirm root-cause indicators without exposing raw logs or secrets.",
    "Investigate which secrets changed or are used by the billing→webhook integration (admin API key, webhook signing secret, service account tokens). We will not expose any raw secrets in messages.",
    "If any secret is affected, prepare a rotation plan and coordinate with your Security team for admin API key resets (Security approval is required for admin API keys).",
    "Perform rotation: create new keys, deploy to consumers, validate traffic and retries in a staging path if possible, then revoke old keys.",
    "After validation, resend pending webhooks from the delivery queue (C) within an agreed maintenance window.",
    "Provide a redacted post-action summary (error codes, counts, timestamps, destinations) and leave audit trails intact for review."
  ],
  "rationale_and_risks": {
    "why_this_flow": "Rotating secrets before resending prevents re-triggering failures due to the same compromised or misconfigured credentials and avoids additional failed deliveries or exposure.",
    "risks_if_skipped": "Resending webhooks with compromised/incorrect keys can cause additional failures or leak sensitive data. Resetting admin keys without Security sign-off violates change controls and is not permitted."
  },
  "estimated_time_and_impact": {
    "investigation_and_redacted_summary": "30–60 minutes to collect and redact relevant error metadata",
    "rotation_and_validation": "30–90 minutes depending on number of consumers and deployment pipelines",
    "resend_pending_webhooks": "10–30 minutes (can be done incrementally)",
    "user_impact": "Possible brief service disruption during key rollout if consumers are not updated simultaneously; we can minimize by rolling new keys in parallel and validating before revoking old keys"
  },
  "what_we_need_from_you": [
    "Choose one: A (redacted summary), B (authorize verification & rotation planning), C (resend after keys are confirmed/rotated), or D (schedule a call).",
    "If you choose B or C: confirm we may coordinate with your Security team for admin API key changes, and provide a preferred maintenance window (e.g., UTC time range).",
    "List any downstream systems or third-party integrators that must be notified or updated during key rotation."
  ],
  "offer": "We can start by sending the redacted error summary immediately if you want more visibility first, or we can draft a rotation runbook and timeline for your approval.",
  "next_step_prompt": "Which option do you want to proceed with (A, B, C, or D)? If B or C, please confirm coordination with Security and provide a preferred maintenance window and contact for Security approval if available."
}

